<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Active Days Import</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f8fafc;color:#172033;font:14px Arial,sans-serif}header,footer{background:#fff;border-bottom:1px solid #e5e7eb}.wrap{max-width:1440px;margin:auto;padding:20px 24px}.top{display:flex;justify-content:space-between;align-items:center}.brand{font-size:24px;font-weight:800}.nav a{margin-left:28px;color:#475569;text-decoration:none}.nav .on{font-weight:800;color:#111827;border-bottom:2px solid #111827;padding-bottom:22px}.hero{display:flex;justify-content:space-between;gap:30px;align-items:center;margin:12px 0 30px}.hero h1{font-size:32px;margin:0 0 7px}.muted{color:#64748b}.steps{display:flex;align-items:center}.step{display:flex;align-items:center;gap:8px;white-space:nowrap;font-size:12px}.dot{width:31px;height:31px;border-radius:50%;display:grid;place-items:center;background:#f1f5f9;color:#94a3b8}.done .dot{background:#e5f7f2;color:#10b981}.active{color:#2563eb;font-weight:700}.active .dot{background:#2563eb;color:white}.line{width:65px;height:1px;background:#e2e8f0;margin:0 10px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:18px}.card{background:white;border:1px solid #dfe4ea;border-radius:12px;padding:22px}.card h2{margin:0 0 18px}.fields{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.field label{display:block;font-size:11px;font-weight:800;color:#4b5563;margin-bottom:6px}.input{width:100%;height:41px;border:1px solid #dce2e9;border-radius:7px;padding:9px}.file{border:1px dashed #bfdbfe;background:#eff6ff;border-radius:9px;padding:17px}.btn{height:40px;padding:0 16px;border:1px solid #dce2e9;border-radius:8px;background:white;font-weight:700;cursor:pointer}.primary{background:#2563eb;border-color:#2563eb;color:white}.btn:disabled{opacity:.45}.warning{display:flex;gap:12px;background:#fff8e8;border:1px solid #f4d49b;border-radius:10px;padding:16px;margin-top:18px}.results{margin-top:22px}.rhead{display:flex;justify-content:space-between;align-items:center}.actions{display:flex;gap:9px}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:20px 0}.kpi{border:1px solid #dfe4ea;border-radius:10px;padding:18px}.kpi label{font-size:11px;font-weight:800;color:#64748b}.kpi strong{display:block;font-size:31px;margin-top:8px}.good{background:#f0fdfa;border-color:#b7eadc}.good label{color:#10b981}.bad{background:#fff7f7;border-color:#fecaca}.bad label,.bad strong{color:#ef4444}.tablewrap{overflow:auto;border:1px solid #dfe4ea;border-radius:10px;margin-top:12px}.tbl{width:100%;border-collapse:collapse;min-width:700px}.tbl th{background:#f3f4f6;text-align:left;padding:11px 15px;font-size:11px}.tbl td{padding:11px 15px;border-top:1px solid #e5e7eb;font-family:monospace}.status{background:#f1f5f9;padding:12px;margin-top:15px;border-radius:8px;white-space:pre-wrap}.hide{display:none}.current{margin-top:20px}footer{border-top:1px solid #e5e7eb;border-bottom:0}@media(max-width:900px){.hero{display:block}.steps{margin-top:20px;overflow:auto}.grid2{grid-template-columns:1fr}}@media(max-width:650px){.fields,.kpis{grid-template-columns:1fr}.nav{display:none}.wrap{padding:16px}.rhead{display:block}.actions{margin-top:12px}}</style></head>
