@include('partials.global-navbar')
<header><div class="wrap top"><div class="brand">Monthly Data</div><nav class="nav"><a href="{{ url('/dashboard-v2') }}">Dashboard</a><a class="on" href="{{ url('/active-days-monthly') }}">Operations</a><a href="{{ url('/reports') }}">Reports</a></nav></div></header>
<main class="wrap"><div class="hero"><div><h1>Active Days Import</h1><div class="muted">Upload and validate monthly active day records for billing generation.</div></div><div class="steps"><span class="step done"><b class="dot">✓</b>Select Period</span><i class="line"></i><span class="step done"><b class="dot">✓</b>Upload File</span><i class="line"></i><span class="step active"><b class="dot">3</b>Preview & Validate</span><i class="line"></i><span class="step"><b class="dot">4</b>Finalize</span></div></div>
<form id="activeDaysForm"><div class="grid2"><section class="card"><h2>▣ Billing Period</h2><div class="fields"><div class="field"><label>BILLING MONTH</label><input class="input" type="month" name="billing_month_date" value="{{ substr((string)$billingMonthDate,0,7) }}" required></div><div class="field"><label>CYCLE START DATE</label><input class="input" type="date" name="cycle_start_date" required></div><div class="field"><label>CYCLE END DATE</label><input class="input" type="date" name="cycle_end_date" required></div></div></section><section class="card"><h2>▤ Source File</h2><div class="file"><div class="field"><label>CSV FILE</label><input type="file" name="upload_file" accept=".csv,.txt" required></div><p><a href="{{ url('/active-days-monthly/template') }}">Download CSV Template</a></p></div></section></div><label class="warning"><input id="replaceExisting" type="checkbox" name="replace_existing" value="1"><span><b>Replace existing selected month data</b><br><span class="muted">Preview identifies existing records before final import.</span></span></label><p><button class="btn primary" type="submit">Preview & Validate</button></p></form>
<section class="card results"><div class="rhead"><div><h2 style="margin-bottom:5px">Validation Results</h2><span class="muted">Review parsed data before finalizing the import.</span></div><div class="actions"><button class="btn" id="reloadRows" type="button">Current Rows</button><button class="btn primary" id="finalImportBtn" type="button" disabled>Proceed to Finalize →</button></div></div><div class="kpis"><div class="kpi"><label>TOTAL ROWS</label><strong id="kTotal">0</strong></div><div class="kpi good"><label>VALID ROWS</label><strong id="kValid">0</strong></div><div class="kpi bad"><label>INVALID ROWS</label><strong id="kInvalid">0</strong></div><div class="kpi"><label>EXISTING UPDATES</label><strong id="kExisting">0</strong></div></div>
<div id="invalidBlock" class="hide"><h3 style="color:#dc2626">⚠ Invalid Records</h3><div class="tablewrap"><table class="tbl"><thead><tr><th>Row</th><th>Company ID</th><th>Active Days</th><th>Error Reason</th></tr></thead><tbody id="invalidRows"></tbody></table></div></div><h3>Valid Records Preview</h3><div class="tablewrap"><table class="tbl"><thead><tr><th>Company ID</th><th>Active Days</th><th>Remarks</th><th>Status</th></tr></thead><tbody id="validRows"><tr><td colspan="4">Upload a CSV and run preview.</td></tr></tbody></table></div><label class="warning"><input id="ackOverwrite" type="checkbox"><span><b>Overwrite Existing Records?</b><br><span id="overwriteText">No preview completed yet.</span></span></label><pre class="status" id="summaryBox">Ready.</pre></section>
<section class="card current"><h2>Current Imported Rows</h2><div class="tablewrap"><table class="tbl"><thead><tr><th>Company ID</th><th>Active Days</th><th>Remarks</th></tr></thead><tbody id="existingRows"></tbody></table></div></section></main><footer><div class="wrap top"><b>© 2026 NodeSky Technologies.</b><span>Monthly billing operations</span></div></footer>
<script>const csrf=@json(csrf_token());let token='';const f=document.getElementById('activeDaysForm'),box=document.getElementById('summaryBox');const esc=v=>String(v??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));function ary(o,ks){for(const k of ks){const v=k.split('.').reduce((a,x)=>a?.[x],o);if(Array.isArray(v))return v}return[]}function n(o,ks,d=0){for(const k of ks){const v=k.split('.').reduce((a,x)=>a?.[x],o);if(v!==undefined&&!isNaN(Number(v)))return Number(v)}return d}function preview(j){token=j.preview_token||'';const ok=ary(j,['valid_rows','accepted_rows','rows.valid']),bad=ary(j,['invalid_rows','rejected_rows','errors','rows.invalid']),total=n(j,['summary.total_rows','total_rows'],ok.length+bad.length),existing=n(j,['summary.existing_updates','summary.existing_rows','existing_updates']);kTotal.textContent=total;kValid.textContent=n(j,['summary.valid_rows','summary.accepted_rows'],ok.length);kInvalid.textContent=n(j,['summary.invalid_rows','summary.rejected_rows'],bad.length);kExisting.textContent=existing;validRows.innerHTML=ok.length?ok.slice(0,100).map(x=>`<tr><td>${esc(x.company_id)}</td><td>${esc(x.active_days)}</td><td>${esc(x.remarks)}</td><td>${esc(x.status||'READY')}</td></tr>`).join(''):'<tr><td colspan="4">No valid rows.</td></tr>';invalidRows.innerHTML=bad.map((x,i)=>`<tr><td>${esc(x.row??x.row_number??i+1)}</td><td>${esc(x.company_id)}</td><td>${esc(x.active_days)}</td><td>${esc(x.error??x.reason??x.errors)}</td></tr>`).join('');invalidBlock.classList.toggle('hide',!bad.length);overwriteText.textContent=existing?existing+' existing records may be updated.':'No existing updates reported.';finalImportBtn.disabled=!token;box.textContent=JSON.stringify(j.summary??j,null,2)}f.onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;box.textContent='Validating...';try{const r=await fetch('{{ url('/active-days-monthly/preview') }}',{method:'POST',headers:{'X-CSRF-TOKEN':csrf,Accept:'application/json'},body:new FormData(f)}),j=await r.json();if(!r.ok)throw Error(JSON.stringify(j));preview(j)}catch(x){box.textContent=x.message}finally{b.disabled=false}};async function rows(){const r=await fetch('{{ url('/active-days-monthly/rows') }}?billing_month_date='+encodeURIComponent(f.billing_month_date.value),{headers:{Accept:'application/json'}}),j=await r.json(),a=Array.isArray(j.rows)?j.rows:[];existingRows.innerHTML=a.length?a.map(x=>`<tr><td>${esc(x.company_id)}</td><td>${esc(x.active_days)}</td><td>${esc(x.remarks)}</td></tr>`).join(''):'<tr><td colspan="3">No rows for selected month.</td></tr>'}reloadRows.onclick=rows;f.billing_month_date.onchange=rows;finalImportBtn.onclick=async()=>{if(!token)return;if(replaceExisting.checked&&!ackOverwrite.checked){box.textContent='Acknowledge overwrite before finalizing.';return}const p={billing_month_date:f.billing_month_date.value,cycle_start_date:f.cycle_start_date.value,cycle_end_date:f.cycle_end_date.value,replace_existing:replaceExisting.checked,preview_token:token};finalImportBtn.disabled=true;try{const r=await fetch('{{ url('/active-days-monthly/import') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,Accept:'application/json'},body:JSON.stringify(p)}),j=await r.json();if(!r.ok)throw Error(JSON.stringify(j));box.textContent=JSON.stringify(j,null,2);token='';rows()}catch(x){box.textContent=x.message;finalImportBtn.disabled=false}};rows();</script></body></html>
